import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"豫","description":"周易集解 - 豫","frontmatter":{"title":"豫","description":"周易集解 - 豫"},"headers":[],"relativePath":"zh/classics/jijie/016.md","filePath":"zh/classics/jijie/016.md"}'),l={name:"zh/classics/jijie/016.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="豫" tabindex="-1">豫 <a class="header-anchor" href="#豫" aria-label="Permalink to “豫”">​</a></h1><h2 id="豫-1" tabindex="-1">豫 <a class="header-anchor" href="#豫-1" aria-label="Permalink to “豫”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>豫，利建侯、行師。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：有大而能謙，必豫。故受之以豫。</p><p>鄭玄曰：言國既大而能謙，則於政事恬豫。雷出地奮，逸豫行出而喜樂之意。</p><p>鄭玄曰：坤，順也。震，動也。順其性而動者，莫不得其所，故謂之豫。豫，喜豫悅樂之貌也。震又謂雷，諸侯之象。坤又為眾，師役之象。故｢利建侯、行師｣矣。</p><p>虞翻曰：復初之四，與小畜旁通。坤為邦國，震為諸侯。初至五，體比象。四利復初，故｢利建侯｣。三至上，體師象，故｢行師｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：豫，剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎！天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服。豫之時義大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>侯果曰：四為卦主，五陰應之，剛志大行，故曰剛應而志行。</p><p>崔憬曰：坤下震上，順以動也。</p><p>虞翻曰：小畜，乾為天。坤為地。如之者，謂天地亦動，以成四時，而況建侯行師。言其皆應而逸豫也。</p><p>《九家易》曰：震為建侯，坤為行師；建侯所以興利，行師所以除害。利興害除，民所逸樂也。天地有生殺，萬物有始終。王者盛衰，亦有迭更，猶武王承亂，而應天地。建侯行師，奉詞除害，民得豫悅，君得安樂也。</p><p>虞翻曰：豫變通小畜。坤為地。動初至三成乾，故天地以順動也。</p><p>虞翻曰：過謂失度，忒，差迭也。謂變初至需，離為日，坎為月，皆得其正，故日月不過。動初時，震為春。至四，兌為秋。至五，坎為冬。離為夏。四時位正，故四時不忒。通變之謂事，蓋此之類。</p><p>虞翻曰：清，猶明也。動初至四，兌為刑。至坎，為罰。坎、兌體正，故刑罰清。坤為民，乾為清，以乾乘坤，故民服。</p><p>案：帝出震，聖人也。坎為法律，刑罰也。坤為眾，順而民服也。</p><p>虞翻曰：順動天地，使日月四時，皆不過差。刑罰清而民服，故義大也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：震在坤上，故言｢雷出地｣。雷，陽氣，亦謂龍也。夏至後，陽氣極而一陰生。陰陽相擊，而成雷聲。雷聲之疾，有龍奮迅豫躍之象，故曰奮豫。</p><p>鄭玄曰：奮，動也。雷動於地上，萬物乃豫也。以者，取其喜佚動搖，猶人至樂，則手欲鼓之，足欲舞之也。崇，充也。殷，盛也。薦，進也。上帝，天也。王者功成作樂，以文得之者，作籥舞；以武得之者，作萬舞；各充其德而為制。祀天帝以配祖考者，使與天同饗其功也。故《孝經》雲：郊祀后稷以配天，宗祀文王於明堂，以配上帝也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，鳴豫，凶。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：應震善鳴，失位，故｢鳴豫，凶｣也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：初六鳴豫，志窮凶也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：體剝蔑貞，故志窮凶也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，介於石，不終日，貞吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：介，纖也。與四為艮，艮為石，故介於石。</p><p>虞翻曰：與小畜通，應在五。終變成離，離為日，得位。欲四爭復初，已得休之。故不終日貞吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不終日，貞吉，以中正也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：得位居中，柔順正一，明豫動之可否，辯趣舍之權宜。假如堅石，不可移變，應時則改，不待終日。故曰豫之正吉。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，盱豫悔，遲有悔。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：盱豫有悔，位不當也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：履非其位，承動豫之主。若其雎盱而豫，悔亦至焉。遲而不從，豫之所疾，進退離悔，位不當也。</p><p>向秀曰：雎盱，小人喜悅、佞媚之貌也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，由豫，大有得，勿疑，朋盍簮。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>侯果曰：為豫之主，眾陰所宗，莫不由之以得其逸。體剛心直，志不懷疑，故得群物依歸，朋從大合，若以簪菾之固括也。</p><p>虞翻曰：由，自從也。據有五陰，坤以眾順，故大有得。得群陰也。坎為疑，故勿疑。小畜兌為朋。盍，合也，坤為盍。戠，聚會也。坎為聚，坤為眾，眾陰竝應，故朋盍戠。戠，舊讀作撍，作宗也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：由豫，大有得，志大行也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：以一陽而眾陰從已合簪交歡，故其志大行也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五：貞疾，恆不死。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：恆，常也。坎為疾。應在坤，坤為死。震為反生。位在震中，與坤體絕。故貞疾恆不死也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五貞疾，乘剛也。恆不死，中未亡也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：六五居尊，而乘於四，四以剛動，非已所乘。乘剛為政，終亦病。若恆不死者，以其中也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，冥豫，成有渝，無咎。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在三。坤為冥。渝，變也。三失位，無應，多凶。變乃得正，體艮成。故成有渝，無咎。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：冥豫在上，何可長也？</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：陽性冥昧，居尊在上，而猶豫悅，故不可長。</p>',75)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
